7	static void expect_triangulate(Halfedge_Mesh& mesh) {
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		// count the number of triangle edges/faces to be generated after triangulation
12		size_t c = 0;
13		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
14			if (!f->boundary && f->degree() > 3) c += f->degree() - 3;
15		}
16	
17		std::map<uint32_t, Vec3> verts;
18		for (Halfedge_Mesh::VertexRef v = mesh.vertices.begin(); v != mesh.vertices.end(); v++) {
19			verts.insert({v->id, v->position});
20		}
21		std::set<uint32_t> edge_ids;
22		for (Halfedge_Mesh::EdgeRef e = mesh.edges.begin(); e != mesh.edges.end(); e++) {
23			edge_ids.insert(e->id);
24		}
25		std::set<uint32_t> face_ids;
26		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
27			face_ids.insert(f->id);
28		}
29	
30		//TODO: halfedges + twin relationships should all be preserved
31		//TODO: shape of boundary faces should be preserved
32	
33		mesh.triangulate();
34	
35		if (auto msg = mesh.validate()) {
36			throw Test::error("Invalid mesh: " + msg.value().second);
37		}
38	
39		// check that all faces are degree 3
40		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
41			if (!f->boundary && f->degree() != 3) {
42				throw Test::error("Triangulation created a non-triangular face!");
43			}
44		}
45	
46		// check for expected number of elements
47		if (numEdges + c != mesh.edges.size()) {
48			throw Test::error("Triangulation did not create the expected number of edges!");
49		}
50		if (numFaces + c != mesh.faces.size()) {
51			throw Test::error("Triangulation did not create the expected number of faces!");
52		}
53	
54		// check that original elements are preserved
55		std::map<uint32_t, Vec3> new_verts;
56		for (Halfedge_Mesh::VertexRef v = mesh.vertices.begin(); v != mesh.vertices.end(); v++) {
57			new_verts.insert({v->id, v->position});
58		}
59		std::set<uint32_t> new_edge_ids;
60		for (Halfedge_Mesh::EdgeRef e = mesh.edges.begin(); e != mesh.edges.end(); e++) {
61			new_edge_ids.insert(e->id);
62		}
63		std::set<uint32_t> new_face_ids;
64		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
65			new_face_ids.insert(f->id);
66		}
67	
68		if (verts != new_verts) {
69			throw Test::error("Triangulation should preserve original vertices!");
70		}
71		std::set<uint32_t> diff;
72		std::set_difference(edge_ids.begin(), edge_ids.end(), new_edge_ids.begin(), new_edge_ids.end(),
73		                    std::inserter(diff, diff.end()));
74		if (diff.size() != 0) {
75			throw Test::error("Triangulation should preserve original edges!");
76		}
77		std::set_difference(face_ids.begin(), face_ids.end(), new_face_ids.begin(), new_face_ids.end(),
78		                    std::inserter(diff, diff.end()));
79		if (diff.size() != 0) {
80			throw Test::error("Triangulation should preserve original faces!");
81		}
82	}
